css:
@import url("https://fonts.googleapis.com/css2?family=Familjen+Grotesk:wght@400;500;600;700&display=swap");
:root{--mg:#D6246E;--mg2:#B01B5A;--mn:#14142B;--mn2:#1E1E3D;--mt:#7FE0C4;--ic:#F4F3FA;--gr:#5C5C74;--ln:#E3E2EE;--f:"Familjen Grotesk",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;font-family:var(--f);font-size:17px;line-height:1.6;color:var(--mn);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-weight:700;margin:0;line-height:1;letter-spacing:-.02em}
.wrap{max-width:1200px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--mt);padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--mt);outline-offset:2px}
.hero{background:var(--mn);color:#fff;overflow:hidden;position:relative}
.nav{display:flex;justify-content:space-between;align-items:center;height:78px;position:relative;z-index:5}.logo{font-weight:700;font-size:22px;text-decoration:none;display:flex;gap:8px;align-items:center}
.menu{display:flex;gap:24px;list-style:none;margin:0;padding:0;align-items:center}.menu a{text-decoration:none}.menu a:hover{color:var(--mt)}.menu .cta{background:var(--mg);padding:9px 16px;border-radius:30px}.menu .cta:hover{color:#fff}
.burger{display:none;background:none;border:2px solid #fff;color:#fff;width:44px;height:40px;border-radius:10px;font-size:20px;cursor:pointer}
.hg{display:grid;grid-template-columns:1.3fr .7fr;gap:30px;align-items:end;padding:50px 0 60px;position:relative;z-index:2}
.hero h1{font-size:clamp(64px,11vw,170px);line-height:.85}.hero h1 span{color:var(--mt);display:block}.hero .sub{display:flex;flex-wrap:wrap;gap:8px 28px;margin:28px 0 0;font-size:20px;color:#D5D4E8}.hero .sub b{color:#fff}
.bars{position:absolute;right:-40px;top:0;bottom:0;width:42%;display:flex;gap:18px;align-items:flex-end;opacity:.4;z-index:1}.bars i{flex:1;background:var(--mn2);border-radius:14px 14px 0 0}.bars i:nth-child(2){background:var(--mg)}.bars i:nth-child(4){background:var(--mt)}
.eb{background:#fff;color:var(--mn);border-radius:20px;padding:22px}.eb small{color:var(--mg2);font-weight:700}.eb .t{display:flex;gap:8px;margin:10px 0 14px}.eb .t div{flex:1;background:var(--ic);border-radius:10px;text-align:center;padding:8px 2px}.eb .t b{display:block;font-size:30px}.eb .t span{font-size:13px;color:var(--gr)}
.btn{display:inline-block;background:var(--mg);color:#fff;text-decoration:none;font:600 17px var(--f);padding:13px 22px;border-radius:30px;border:0;cursor:pointer}.btn.d{background:var(--mn)}
.logos{background:var(--mn2);color:#A9A8C6}.logos .wrap{display:flex;flex-wrap:wrap;justify-content:space-between;gap:12px 30px;padding-top:18px;padding-bottom:18px;font-weight:600;font-size:18px}
section{padding:86px 0}.sh{display:flex;justify-content:space-between;align-items:flex-end;flex-wrap:wrap;gap:14px;margin-bottom:28px}.sh h2{font-size:clamp(44px,6vw,84px)}.sh p{color:var(--gr);margin:8px 0 0;max-width:32em}
.chips{display:flex;flex-wrap:wrap;gap:8px}.chips button{font:600 15px var(--f);background:var(--ic);border:0;border-radius:30px;padding:9px 16px;cursor:pointer;color:var(--mn)}.chips button[aria-pressed=true]{background:var(--mn);color:#fff}
.sp{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}.spk img{width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:20px;filter:grayscale(1)}.spk:hover img{filter:none}
.spk h3{font-size:22px;margin-top:12px}.spk p{margin:2px 0 0;color:var(--gr);font-size:15px}.spk .tk{display:inline-block;margin-top:8px;font-size:13px;font-weight:700;border-radius:20px;padding:2px 10px}
.tk.Product{background:#FCE4EE;color:var(--mg2)}.tk.Engineering{background:#DDF6EF;color:#1D7A61}.tk.Design{background:#E6E4FB;color:#4A3FB5}
.ag{background:var(--ic)}.agt{display:flex;flex-wrap:wrap;gap:10px;justify-content:space-between;margin-bottom:18px}
.days{display:inline-flex;background:#fff;border-radius:30px;padding:4px}.days button{font:700 16px var(--f);border:0;background:transparent;padding:10px 20px;border-radius:30px;cursor:pointer;color:var(--mn)}.days button[aria-pressed=true]{background:var(--mg);color:#fff}
.mine{font:600 15px var(--f);background:#fff;border:2px solid var(--mn);border-radius:30px;padding:8px 16px;cursor:pointer;color:var(--mn)}.mine[aria-pressed=true]{background:var(--mn);color:#fff}
.sl{background:#fff;border-radius:16px;display:grid;grid-template-columns:110px 1fr auto;gap:18px;align-items:center;padding:16px 20px;margin-bottom:10px}
.sl .tm{font-size:22px;font-weight:700}.sl h3{font-size:20px;letter-spacing:-.01em}.sl p{margin:4px 0 0;color:var(--gr);font-size:15px}.sl .tk{margin-left:8px;vertical-align:middle;font-size:12px;border-radius:20px;padding:2px 8px;font-weight:700}
.sl button{width:44px;height:44px;border-radius:50%;border:2px solid var(--ln);background:#fff;font-size:20px;cursor:pointer;color:var(--gr)}.sl button[aria-pressed=true]{background:var(--mt);border-color:var(--mt);color:var(--mn)}
.sl.brk{background:transparent;border:2px dashed #CFCDE2}.none{background:#fff;border-radius:16px;padding:24px;text-align:center}
.tix .tg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.tc{border:2px solid var(--ln);border-radius:22px;padding:26px;display:flex;flex-direction:column}.tc.hot{border-color:var(--mg);box-shadow:8px 8px 0 var(--mg)}
.tc h3{font-size:28px}.tc .pr{font-size:52px;font-weight:700;margin:10px 0 0;line-height:1}.tc .was{color:var(--gr);text-decoration:line-through;font-size:16px;margin:4px 0 12px}.tc ul{padding-left:18px;margin:0 0 18px;flex:1}.tc li{margin:5px 0}
.qt{display:flex;align-items:center;gap:10px;margin-bottom:10px}.qt button{width:40px;height:40px;border-radius:50%;border:2px solid var(--mn);background:#fff;font-size:20px;cursor:pointer}.qt output{font-weight:700;font-size:22px;min-width:26px;text-align:center}
.cart{margin-top:24px;background:var(--mn);color:#fff;border-radius:22px;padding:22px 26px;display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}.cart b{font-size:38px}.cart span{color:#C4C3DB}
.msg{visibility:hidden;margin:12px 0 0;font-weight:600;color:var(--mg2)}.msg.on{visibility:visible}
.venue{background:var(--mn);color:#fff}.vg{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center}.venue h2{font-size:clamp(40px,5vw,70px)}.venue p{color:#C4C3DB}.venue img{border-radius:22px;width:100%;aspect-ratio:4/3;object-fit:cover}
footer{background:var(--mn2);color:#A9A8C6;padding:28px 0;font-size:15px}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.hg,.vg{grid-template-columns:1fr}.bars{width:60%;opacity:.35}.sp{grid-template-columns:1fr 1fr}.tix .tg{grid-template-columns:1fr}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:78px;left:0;right:0;background:var(--mn);flex-direction:column;align-items:flex-start;padding:18px 22px;z-index:30}.menu.open{display:flex}.sl{grid-template-columns:1fr auto}.sl .tm{grid-column:1/-1;font-size:18px}.bars{display:none}.tc.hot{box-shadow:5px 5px 0 var(--mg)}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);const U=i=>`https://images.unsplash.com/photo-${i}?w=500&q=75&auto=format&fit=crop`;
const S=[["Ana Ribeiro","Head of Product, Lendwise","Product","1573496359142-b8d87734a5a2"],["Kwame Asante","Staff Engineer, Parcelly","Engineering","1507003211169-0a1dd7228f2d"],["Mei Lin","Design Director, Notewise","Design","1534528741775-53994a69daeb"],["Jonas Weber","CTO, Railpath","Engineering","1500648767791-00dcc994a43e"],["Priya Nair","VP Product, Habitly Health","Product","1544005313-94ddf0286df2"],["Luca Ferraro","Principal Designer, Tidewater","Design","1535713875002-d1d0cf377fde"],["Sara Okoye","Engineering Manager, Dotfield","Engineering","1573497019940-1c28c88b4f3e"],["Tom Brandt","Founder, Shelfspace","Product","1472099645785-5658abf4ff4e"]];
function sp(t){$('sp').innerHTML=S.filter(s=>t==='all'||s[2]===t).map(s=>`<article class="spk"><img src="${U(s[3])}" alt="${s[0]}" width="500" height="500" loading="lazy"><h3>${s[0]}</h3><p>${s[1]}</p><span class="tk ${s[2]}">${s[2]}</span></article>`).join('')}
$('sf').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('sf').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));sp(b.dataset.t)};sp('all');
const A={1:[["09:00","Opening: what we got wrong in 2026","Tom Brandt","Product"],["10:00","Shipping weekly without breaking things","Kwame Asante","Engineering"],["10:00","Designing for tired people","Mei Lin","Design"],["11:30","Coffee and demos",null,null],["12:00","Saying no to your biggest customer","Ana Ribeiro","Product"],["14:00","Our database migration, hour by hour","Jonas Weber","Engineering"],["15:30","Accessible by default, not by audit","Luca Ferraro","Design"],["19:00","Riverside party",null,null]],2:[["09:30","Small teams, big products","Priya Nair","Product"],["10:30","Growing engineers into managers","Sara Okoye","Engineering"],["10:30","Design systems people actually use","Mei Lin","Design"],["12:00","Lunch",null,null],["13:30","Pricing experiments that worked","Ana Ribeiro","Product"],["14:30","On-call without burning out","Kwame Asante","Engineering"],["16:00","Closing panel and goodbye","All speakers","Product"]]};
let day=1,only=false;const my=new Set();
function ag(){let r=A[day].map((s,i)=>[s,day+'-'+i]);if(only)r=r.filter(([s,k])=>my.has(k));$('mine').textContent=`My schedule (${my.size})`;
$('sl').innerHTML=r.length?r.map(([s,k])=>s[2]?`<div class="sl"><span class="tm">${s[0]}</span><div><h3>${s[1]}<span class="tk ${s[3]}">${s[3]}</span></h3><p>${s[2]}</p></div><button type="button" data-k="${k}" aria-pressed="${my.has(k)}" aria-label="${my.has(k)?'Remove from':'Add to'} my schedule: ${s[1]}">${my.has(k)?'★':'☆'}</button></div>`:`<div class="sl brk"><span class="tm">${s[0]}</span><div><h3>${s[1]}</h3></div><span></span></div>`).join(''):'<p class="none">No talks picked for this day yet. Tap a star to add one.</p>'}
$('days').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('days').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));day=+b.dataset.d;ag()};
$('sl').onclick=e=>{const b=e.target.closest('button');if(!b)return;const k=b.dataset.k;my.has(k)?my.delete(k):my.add(k);ag()};$('mine').onclick=()=>{only=!only;$('mine').setAttribute('aria-pressed',only);ag()};ag();
const T=[["Standard",349,499,["Both days, all tracks","Lunch and party","Talk recordings after"]],["Team pack of 5",1495,2245,["5 standard tickets","Reserved table at lunch","One invoice"],1],["Student",99,149,["Both days, all tracks","Student ID needed at the door","Limited to 150"]]];const q=[1,0,0];
function tg(){$('tg').innerHTML=T.map((t,i)=>`<div class="tc${t[4]?' hot':''}"><h3>${t[0]}</h3><div class="pr">€${t[1].toLocaleString('en-US')}</div><div class="was">€${t[2].toLocaleString('en-US')} after early bird</div><ul>${t[3].map(x=>`<li>${x}</li>`).join('')}</ul><div class="qt" role="group" aria-label="${t[0]} quantity"><button type="button" data-i="${i}" data-d="-1" aria-label="Fewer">−</button><output>${q[i]}</output><button type="button" data-i="${i}" data-d="1" aria-label="More">+</button></div></div>`).join('');
const n=q.reduce((a,b)=>a+b,0),tot=q.reduce((a,x,i)=>a+x*T[i][1],0);$('ci').textContent=n?q.map((x,i)=>x?`${x} x ${T[i][0]}`:'').filter(Boolean).join(', '):'No tickets yet';$('ct').textContent='€'+tot.toLocaleString('en-US')}
$('tg').onclick=e=>{const b=e.target.closest('button');if(!b)return;const i=+b.dataset.i;q[i]=Math.max(0,Math.min(20,q[i]+ +b.dataset.d));tg()};tg();
$('buy').onclick=()=>{const m=$('msg');m.textContent=q.some(x=>x)?`Great. ${$('ci').textContent} saved. In your own site, this button would open your payment page.`:'Add at least one ticket first.';m.classList.add('on')};
const E=new Date('2027-01-15T23:59:00');function eb(){const s=Math.max(0,Math.floor((E-new Date())/1000));$('eD').textContent=Math.floor(s/86400);$('eH').textContent=Math.floor(s%86400/3600);$('eM').textContent=Math.floor(s%3600/60)}eb();setInterval(eb,30000);
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
